import sys
sys.path.insert(0, '.')
from src.coin_change import coin_change


def test_zero_amount():
    assert coin_change([1, 5, 10], 0) == 0


def test_exact_coin():
    assert coin_change([1, 2, 5], 5) == 1


def test_greedy_wrong():
    # greedy picks 6 then can't finish; DP finds 5+5+1=3
    assert coin_change([1, 2, 5], 11) == 3


def test_impossible():
    assert coin_change([2], 3) == -1
